import pandas as pdimport foodomicspy as fdef test_crop_spectra():    df = pd.DataFrame(        {            900.0: [1, 2],            1000.0: [3, 4],            1100.0: [5, 6],            1200.0: [7, 8],        },        index=["sample_1", "sample_2"],    )    result = f.utils.crop_spectra(        df,        (1000, 1100),    )    assert result.columns.tolist() == [1000.0, 1100.0]    assert result.index.equals(df.index)def test_crop_spectra_multiple_regions():    df = pd.DataFrame(        {            900.0: [1, 2],            1000.0: [3, 4],            1100.0: [5, 6],            1200.0: [7, 8],        },        index=["sample_1", "sample_2"],    )    result = f.utils.crop_spectra(        df,        (900, 1000),        (1200, 1200),    )    assert result.columns.tolist() == [900.0, 1000.0, 1200.0]def test_crop_spectra_accepts_reversed_region():    df = pd.DataFrame(        {            900.0: [1, 2],            1000.0: [3, 4],            1100.0: [5, 6],            1200.0: [7, 8],        }    )    result = f.utils.crop_spectra(        df,        (1100, 1000),    )    assert result.columns.tolist() == [1000.0, 1100.0]def test_sort_sample_id_abc():    df = pd.DataFrame(        {"value": [1, 2, 3, 4]},        index=[            "C02_b",            "C01_c",            "C01_a",            "C02_a",        ],    )    result = f.utils.sort_sample_id_abc(df)    assert result.index.tolist() == [        "C01_a",        "C01_c",        "C02_a",        "C02_b",    ]